"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacyStreamingText from "../beautiful-ui/primitives/StreamingText";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type StreamingTextProps = NonNullable<ComponentProps<typeof LegacyStreamingText>>;

export const StreamingText = forwardRef<HTMLDivElement, StreamingTextProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacyStreamingText {...props} />
  </BeautifulUIRoot>
));

StreamingText.displayName = "StreamingText";

export default StreamingText;

"use client";

import "../beautiful-ui.css";

import { useEffect, useId, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { springs } from "@/lib/springs";
import { useReducedMotion } from "../hooks/useReducedMotion";

/* ─────────────────────────────────────────────────────────
 * STREAMING TEXT
 * Words resolve out of blur, inline citations appear in
 * context, then actions and follow-up prompts become usable.
 * ───────────────────────────────────────────────────────── */

const WORD_MS = 55;
const HOLD_MS = 3400;
const RESPONSE_TEXT =
  "Pistachio is your fastest-growing flavor — sales are up 23% this month and margins beat vanilla by 8 points. Stone-fruit flavors are trending in the same range.";

type Token = { text: string; cite?: boolean };

const TOKENS: Token[] = [
  ..."Pistachio is your fastest-growing flavor — sales are up 23% this month and margins beat vanilla by 8 points."
    .split(" ")
    .map((text) => ({ text })),
  { text: "", cite: true },
  ..."Stone-fruit flavors are trending in the same range.".split(" ").map((text) => ({ text })),
];

const FOLLOW_UPS = ["Which flavors sell best in winter", "Compare gelato and soft serve margins"];

const SOURCE_IMAGES = {
  scoop:
    "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='16' fill='%231f7a5f'/%3E%3Cpath d='M20 36c0 7 5.4 12 12 12s12-5 12-12H20Z' fill='%23fff'/%3E%3Ccircle cx='32' cy='25' r='11' fill='%23bff3dd'/%3E%3Cpath d='M24 24c4-7 13-7 17 0' fill='none' stroke='%231f7a5f' stroke-width='4' stroke-linecap='round'/%3E%3C/svg%3E",
  trends:
    "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='16' fill='%232f6fec'/%3E%3Cpath d='M15 43 27 31l8 7 14-18' fill='none' stroke='%23fff' stroke-width='7' stroke-linecap='round' stroke-linejoin='round'/%3E%3Ccircle cx='49' cy='20' r='5' fill='%23bfe0ff'/%3E%3C/svg%3E",
  market:
    "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='16' fill='%23e56d24'/%3E%3Cpath d='M17 45V25h8v20h-8Zm11 0V16h8v29h-8Zm11 0V30h8v15h-8Z' fill='%23fff'/%3E%3Cpath d='M16 49h32' stroke='%23ffd6b8' stroke-width='4' stroke-linecap='round'/%3E%3C/svg%3E",
};

const SOURCES = [
  {
    name: "Scoop Data",
    domain: "scoopdata.io",
    href: "https://scoopdata.io/",
    image: SOURCE_IMAGES.scoop,
  },
  {
    name: "Trends Index",
    domain: "trends.google.com",
    href: "https://trends.google.com/trends/",
    image: SOURCE_IMAGES.trends,
  },
  {
    name: "Market Basket",
    domain: "marketbasket.io",
    href: "https://marketbasket.io/",
    image: SOURCE_IMAGES.market,
  },
];

function sourceImage(source: (typeof SOURCES)[number]) {
  return source.image;
}

function SourceChip({ reducedMotion }: { reducedMotion: boolean }) {
  const source = SOURCES[0];
  return (
    <a
      href={source.href}
      target="_blank"
      rel="noreferrer"
      className="ml-0 mr-1 inline-flex h-4.5 translate-y-[-1px] items-center gap-1 rounded-[5px]
        bg-[var(--inset)] pr-[3px] pl-[3px] align-middle font-mono text-[11px] text-[var(--ink-2)] shadow-[var(--shadow-hairline)]
        transition-[background-color,color,transform] duration-80 hover:bg-[var(--hover)] hover:text-[var(--ink)] active:scale-[0.98]"
      style={{
        animation: reducedMotion ? "none" : "pop-in 240ms cubic-bezier(0.23,1,0.32,1) both",
      }}
    >
      <img src={sourceImage(source)} alt="" className="source-avatar size-3 rounded-[3px]" />
      <span>{source.domain}</span>
    </a>
  );
}

const ACTION_ICONS: React.ReactNode[] = [
  <g key="copy">
    <rect x="9" y="9" width="12" height="12" rx="2.5" />
    <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
  </g>,
  <path key="retry" d="M21 12a9 9 0 1 1-2.64-6.36M21 3v6h-6" />,
  <path
    key="up"
    d="M7 10v12M15 5.88L14 10h5.83a2 2 0 0 1 1.92 2.56l-2.33 8A2 2 0 0 1 17.5 22H4a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2h2.76a2 2 0 0 0 1.79-1.11L12 2a3.13 3.13 0 0 1 3 3.88z"
  />,
  <path
    key="down"
    d="M17 14V2M9 18.12L10 14H4.17a2 2 0 0 1-1.92-2.56l2.33-8A2 2 0 0 1 6.5 2H20a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2h-2.76a2 2 0 0 0-1.79 1.11L12 22a3.13 3.13 0 0 1-3-3.88z"
  />,
];

export type StreamingTextAction = "copy" | "retry" | "helpful" | "not-helpful";

const ACTIONS: { key: StreamingTextAction; label: string }[] = [
  { key: "copy", label: "Copy response" },
  { key: "retry", label: "Regenerate response" },
  { key: "helpful", label: "Mark response as helpful" },
  { key: "not-helpful", label: "Mark response as not helpful" },
];

export interface StreamingTextProps {
  variant?: string;
  /** restart the stream after a hold; turn off when embedding in a real thread */
  loop?: boolean;
  /** fill the parent width instead of the gallery's fixed measure */
  fill?: boolean;
  onDone?: () => void;
  onAction?: (action: StreamingTextAction) => void;
  onFollowUp?: (prompt: string) => void;
  onSourcesOpenChange?: (open: boolean) => void;
}

export default function StreamingText({
  loop = false,
  fill = false,
  onDone,
  onAction,
  onFollowUp,
  onSourcesOpenChange,
}: StreamingTextProps) {
  const reducedMotion = useReducedMotion();
  const [count, setCount] = useState(0);
  const [sourcesOpen, setSourcesOpen] = useState(false);
  const [feedback, setFeedback] = useState<"helpful" | "not-helpful" | null>(null);
  const [selectedFollowUp, setSelectedFollowUp] = useState<string | null>(null);
  const [actionStatus, setActionStatus] = useState("");
  const [hasCompleted, setHasCompleted] = useState(false);
  const completedRef = useRef(false);
  const sourcesId = useId();
  const done = count >= TOKENS.length;

  useEffect(() => {
    if (reducedMotion && !done) {
      setCount(TOKENS.length);
      return;
    }
    if (done) {
      if (!completedRef.current) {
        completedRef.current = true;
        setHasCompleted(true);
        onDone?.();
      }
      if (!loop || reducedMotion) return;
      const t = setTimeout(() => {
        setCount(0);
        completedRef.current = false;
      }, HOLD_MS);
      return () => clearTimeout(t);
    }
    const t = setTimeout(() => setCount((c) => c + 1), WORD_MS);
    return () => clearTimeout(t);
  }, [count, done, loop, onDone, reducedMotion]);

  const handleAction = (action: StreamingTextAction) => {
    onAction?.(action);
    if (action === "retry") {
      completedRef.current = false;
      setHasCompleted(false);
      setActionStatus("Regenerating response");
      setSelectedFollowUp(null);
      setSourcesOpen(false);
      onSourcesOpenChange?.(false);
      setCount(reducedMotion ? TOKENS.length : 0);
      return;
    }
    if (action === "copy") {
      const write = navigator.clipboard?.writeText(RESPONSE_TEXT);
      if (!write) {
        setActionStatus("Could not copy response");
        return;
      }
      void write
        .then(() => setActionStatus("Response copied"))
        .catch(() => setActionStatus("Could not copy response"));
      return;
    }
    setFeedback(action);
    setActionStatus(action === "helpful" ? "Marked as helpful" : "Marked as not helpful");
  };

  return (
    <div className={fill ? "w-full" : "min-h-[15.5rem] w-full max-w-95"}>
      <span className="sr-only" role="status" aria-live="polite" aria-atomic="true">
        {hasCompleted ? "Response ready" : ""}
      </span>
      <p className="text-[13px] leading-relaxed text-[var(--ink)]">
        {TOKENS.slice(0, count).map((token, i) =>
          token.cite ? (
            <SourceChip key={i} reducedMotion={reducedMotion} />
          ) : (
            <span key={i} className="inline">
              {token.text}{" "}
            </span>
          ),
        )}
        {!done && (
          <span
            className="ml-0.5 inline-block h-3 w-0.5 translate-y-0.5 rounded-full bg-[var(--ink)]"
            style={{ animation: reducedMotion ? "none" : "fade-in 160ms ease-out both" }}
          />
        )}
      </p>

      {/* action icons row */}
      {done && (
        <div className="mt-2 flex items-center gap-0.5">
          {ACTIONS.map((action, i) => (
            <button
              key={action.key}
              type="button"
              aria-label={action.label}
              aria-pressed={
                action.key === "helpful" || action.key === "not-helpful"
                  ? feedback === action.key
                  : undefined
              }
              onClick={() => handleAction(action.key)}
              className="flex size-6 items-center justify-center rounded-[var(--radius-control)] text-[var(--ink-3)]
              transition-[background-color,color,transform] duration-80 hover:bg-[var(--hover-2)] hover:text-[var(--ink-2)] active:scale-[0.98]"
            >
              <svg
                width="15"
                height="15"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.8"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                {ACTION_ICONS[i]}
              </svg>
            </button>
          ))}
          <button
            type="button"
            aria-expanded={sourcesOpen}
            aria-controls={sourcesId}
            aria-label={`${sourcesOpen ? "Hide" : "Show"} ${SOURCES.length} sources`}
            onClick={() => {
              const next = !sourcesOpen;
              setSourcesOpen(next);
              onSourcesOpenChange?.(next);
            }}
            className="ml-1.5 flex items-center gap-1.5 rounded-[var(--radius-control)] px-1 py-0.5 text-left transition-[background-color,transform] duration-80 hover:bg-[var(--hover)] active:scale-[0.98]"
          >
            <span className="flex -space-x-1">
              {SOURCES.map((source) => (
                <img
                  key={source.domain}
                  src={sourceImage(source)}
                  alt=""
                  className="source-avatar size-3.5 rounded-full bg-[var(--surface)] shadow-[0_0_0_1.5px_var(--canvas)]"
                />
              ))}
            </span>
            <span className="text-[12px] text-[var(--ink-2)]">{SOURCES.length} sources</span>
          </button>
        </div>
      )}

      <span className="sr-only" role="status" aria-live="polite" aria-atomic="true">
        {actionStatus}
      </span>

      <AnimatePresence initial={false}>
        {done && sourcesOpen && (
          <motion.div
            id={sourcesId}
            initial={reducedMotion ? false : { height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={reducedMotion ? { duration: 0 } : springs.slow}
            className="overflow-hidden"
          >
            <div className="mt-2 flex flex-col rounded-[var(--radius-menu)] bg-[var(--inset)] p-1 shadow-[var(--shadow-hairline)]">
              {SOURCES.map((source) => (
                <a
                  key={source.domain}
                  href={source.href}
                  target="_blank"
                  rel="noreferrer"
                  className="flex min-h-8 items-center gap-2 rounded-[var(--radius-control)] px-2 py-1.5 text-[13px] text-[var(--ink-2)] transition-[background-color,color,transform] duration-80 hover:bg-[var(--hover)] hover:text-[var(--ink)] active:scale-[0.98]"
                >
                  <img
                    src={sourceImage(source)}
                    alt=""
                    className="source-avatar size-4 rounded-[4px]"
                  />
                  <span className="animated-underline">{source.name}</span>
                  <span className="ml-auto font-mono text-[11px] text-[var(--ink-3)]">
                    {source.domain}
                  </span>
                </a>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* follow-ups */}
      {done && (
        <div className="mt-2.5">
          <p className="text-[12px] font-medium text-[var(--ink-2)]">Follow-ups</p>
          <div className="mt-0.5 flex flex-col">
            {FOLLOW_UPS.map((text, i) => (
              <button
                key={text}
                type="button"
                aria-label={`Ask follow-up: ${text}`}
                aria-pressed={selectedFollowUp === text}
                onClick={() => {
                  setSelectedFollowUp(text);
                  setActionStatus(`Selected follow-up: ${text}`);
                  onFollowUp?.(text);
                }}
                className="-mx-1.5 flex items-center gap-2 rounded-[var(--radius-control)] border-b border-[var(--line)]
                px-1.5 py-1.5 text-left text-[13px] text-[var(--ink)] transition-[background-color,transform]
                duration-80 hover:bg-[var(--hover-2)] active:scale-[0.98]"
                style={{
                  animation: reducedMotion
                    ? "none"
                    : `fade-up 240ms cubic-bezier(0.23,1,0.32,1) ${i * 80}ms both`,
                }}
              >
                <svg
                  width="11"
                  height="11"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="var(--ink-3)"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  className="shrink-0"
                >
                  <path d="M9 10l-5 5 5 5" />
                  <path d="M20 4v7a4 4 0 0 1-4 4H4" />
                </svg>
                {text}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import "./beautiful-ui.css";
import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { SurfaceProvider, useSurface } from "@/lib/surface-context";
import { useShapeVariant } from "@/lib/shape-context";

export type BeautifulUIRootProps = HTMLAttributes<HTMLDivElement>;

type AdapterStyle = CSSProperties & Record<`--${string}`, string | number>;

function clampSurface(level: number) {
  return Math.max(1, Math.min(8, level));
}

function createAdapterStyle(
  substrate: number,
  surface: number,
  style?: CSSProperties,
): AdapterStyle {
  const inset = clampSurface(substrate + 1);
  const overlay = clampSurface(surface + 2);
  const raisedOverlay = clampSurface(surface + 4);

  return {
    "--page": `var(--surface-${substrate})`,
    "--canvas": `var(--surface-${substrate})`,
    "--surface": `var(--surface-${surface})`,
    "--inset": `var(--surface-${inset})`,
    "--tooltip-bg": `var(--surface-${overlay})`,
    "--overlay-surface": `var(--surface-${overlay})`,
    "--overlay-raised": `var(--surface-${raisedOverlay})`,
    ...style,
  };
}

function useBeautifulUIScope(offset = 2) {
  const substrate = useSurface();
  const surface = clampSurface(substrate + offset);
  const shape = useShapeVariant();

  return {
    shape,
    substrate,
    surface,
    style: createAdapterStyle(substrate, surface),
  };
}

/**
 * Internal compatibility boundary for the adapted primitives. It has no layout
 * box of its own: public components use it internally so consumers inherit the
 * active BoringUI theme, surface level, and radius mode without a wrapper.
 */
export const BeautifulUIRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", "contents", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIRoot.displayName = "BeautifulUIRoot";

/** Applies the same BoringUI scope to content rendered in a body portal. */
export const BeautifulUIPortalRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIPortalRoot.displayName = "BeautifulUIPortalRoot";

export default BeautifulUIRoot;

